asset t{size 5x2 output point state
 echo(image:layer)->layer{return image}
 abandon(){layer gone{pixel(0,1,#fff) return;}pixel(1,1,#fff)}
 draw{pixel(0,0,#11223380) pixel(1,0,#112233)
 layer image(alpha=surface.legacy){pixel(0,0,#ff000080) pixel(1,0,#0000ff00)
 layer nested{pixel(2,0,#929ca8)}surface.paint(nested)}
 surface.paint(echo(image)) abandon()
 for i in 0..3{layer loop{pixel(i,1,#c09060) if(i==0){continue}break;}}
 surface.paint(loop) state={seed&65535,seed>>16}}}

asset t{size 8x1 input u32 layer=1 output point p
 const i32 Legacy=surface.legacy
 const(x:i32)->i32{return x}
 sampler(x:i32)->i32{return x}
 weighted(x:i32)->i32{return x}
 density(x:i32)->i32{return x}
 to(x:i32)->i32{return x}
 with(x:i32)->i32{return x}
 distribution(x:i32)->i32{return x}
 draw{value=const(sampler(weighted(density(to(with(distribution(2)))))))
 pixel(layer,0,#929ca8) p={value,Legacy}}}
